def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target object. Do not place it as the goal item; put it back if needed, then search for the requested target type.'
    elif stage == 'take_target' and target:
        msg = 'A requested target type is available here. Take the target instead of continuing to search or taking a different object.'
    elif stage == 'transform' and target and verb:
        msg = 'You are carrying the target. Use the admissible ' + verb + ' action on it before placing it at the destination.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the target to the requested destination type ' + dest + ' and use the admissible put action there.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the requested destination with the target. Put the target in/on the ' + dest + ' now.'
    elif stage == 'find_target' and target and (val(ctx, 'predicates.same_action_repeated', False) or val(ctx, 'predicates.same_observation_repeated', False) or val(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers and surfaces for the requested target type ' + target + '; do not place a different object.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

